exec('import os\nimport sys\nimport tty\nimport time\nimport termios\nimport shutil\nimport subprocess\nimport atexit\nimport signal\n\nMIN_COLS = 64\n\na = "\\033[1;30m"\nm = "\\033[1;31m"\nh = "\\033[1;32m"\nk = "\\033[1;33m"\nc = "\\033[1;36m"\np = "\\033[1;37m"\nr = "\\033[0m"\n\nfd = sys.stdin.fileno()\nold_settings = termios.tcgetattr(fd)\n\n\ndef hide_cursor():\n    sys.stdout.write("\\033[?25l")\n    sys.stdout.flush()\n\n\ndef show_cursor():\n    sys.stdout.write("\\033[?25h")\n    sys.stdout.flush()\n\n\ndef restore_terminal():\n    try:\n        termios.tcsetattr(fd, termios.TCSADRAIN, old_settings)\n    except Exception:\n        pass\n\n\ndef cleanup():\n    restore_terminal()\n    show_cursor()\n\n\ndef signal_handler(signum, frame):\n    cleanup()\n    raise SystemExit(0)\n\n\natexit.register(cleanup)\nsignal.signal(signal.SIGINT, signal_handler)\nsignal.signal(signal.SIGTERM, signal_handler)\n\n\ndef auto_update():\n    try:\n        with open(os.devnull, "w") as devnull:\n            result = subprocess.run(\n                ["git", "remote", "-v"],\n                stdout=subprocess.PIPE,\n                stderr=devnull,\n                text=True,\n            )\n\n            if result.stdout.strip():\n                subprocess.run(\n                    ["git", "pull"],\n                    stdout=devnull,\n                    stderr=devnull,\n                    check=False,\n                )\n    except Exception:\n        pass\n\n\nauto_update()\ntry:\n    tty.setcbreak(fd)\n    hide_cursor()\n\n    last_status = None\n\n    while True:\n        cols = shutil.get_terminal_size().columns\n\n        if cols >= MIN_COLS:\n            status = (\n                "OK",\n                f"""\n\\033[102m   {r} {p}Ukuran Layar {h}Sudah{p} Sesuai.\\n"""\n            )\n        else:\n            status = (\n                "SMALL",\n                f""" Tidak Mengerti Bisa Chat 0895404759092\n\\033[101m   {r} {p}Ukuran Layar {m}Belum{p} Sesuai.{p}Silahkan Cubit Layar\\n"""\n            )\n\n        if status != last_status:\n            print(status[1], end="", flush=True)\n            last_status = status\n\n        if cols >= MIN_COLS:\n            time.sleep(1)\n\n            cleanup()\n\n            try:\n                subprocess.run(\n                    [sys.executable, "apps.py"],\n                    stdin=sys.stdin,\n                    stdout=sys.stdout,\n                    stderr=sys.stderr,\n                )\n            finally:\n                cleanup()\n\n            break\n\n        time.sleep(0.05)\n\nexcept KeyboardInterrupt:\n    pass\n\nfinally:\n    cleanup()\n')